69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
75	
76	    /**
77	     * Dedicated logger for the welcome notification enqueued when an owner is successfully created.
78	     * The emitted line carries the owner's id and its unified {@link Owner#getMemberId() memberId} so
79	     * downstream notification consumers can address the welcome to the newly registered owner.
80	     */
81	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
82	
83	    /**
84	     * Serializes {@link OwnerCreatedEvent structured audit events} to their JSON form. Stateless and
85	     * thread-safe, so a single shared instance serves every create.
86	     */
87	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
88	
89	    /**
90	     * Monotonically increasing sequence stamped onto each {@link OwnerCreatedEvent OWNER_CREATED}
91	     * event, so the ordering of creates is recoverable from the audit stream alone. Shared across all
92	     * creates (hence {@code static}) and incremented once per emitted event.
93	     */
94	    private static final AtomicLong AUDIT_SEQ = new AtomicLong();
95	
96	    /**
97	     * Immutable structured audit event emitted (as JSON) alongside the human-readable audit line when
98	     * an owner is created. Its {@code memberId} component carries the owner's <em>primary
99	     * identifier</em>, the unified {@link Owner#getMemberId() memberId}, so downstream consumers always
100	     * read the owner's primary identifier from the same event.
101	     *
102	     * <p>This is schema version 2: it carries a {@code schemaVersion} of {@code 2} and the owner's
103	     * {@code ownerSegment}, recomputed from the owner's version-2 identity, alongside the fields the
104	     * version-1 event carried. The component order matches the serialized field order
105	     * {@code {schemaVersion, seq, ownerId, memberId, membershipLevel, ownerSegment, event}}.
106	     */
107	    private record OwnerCreatedEvent(int schemaVersion, long seq, Integer ownerId, String memberId,
108	                                     Integer membershipLevel, String ownerSegment, String event) {
109	
110	        private static final String OWNER_CREATED = "OWNER_CREATED";
111	
112	        /**
113	         * The audit event schema version. Version 2 groups the owner's identity under the response's
114	         * {@code identity} object and derives it with the version-2 algorithm; the event records the
115	         * version it was emitted under so downstream consumers can tell the schemas apart.
116	         */
117	        private static final int SCHEMA_VERSION = 2;
118	
119	        /**
120	         * Assemble the audit event for a just-persisted owner. Every owner-derived component is read
121	         * through a single named accessor ({@link #ownerId(Owner)}, {@link #primaryIdentifier(Owner)},
122	         * {@link #membershipLevel(Owner)}, {@link #ownerSegment(Owner)}), so the event's schema — the
123	         * fields it carries and how each one is derived from the persisted owner — is defined in one
124	         * place and extended there.
125	         */
126	        static OwnerCreatedEvent of(long seq, Owner owner) {
127	            return new OwnerCreatedEvent(SCHEMA_VERSION, seq, ownerId(owner), primaryIdentifier(owner),
128	                membershipLevel(owner), ownerSegment(owner), OWNER_CREATED);
129	        }
130	
131	        private static Integer ownerId(Owner owner) {
132	            return owner.getId();
133	        }
134	
135	        /**
136	         * The owner's primary identifier: its unified {@link Owner#getMemberId() memberId}.
137	         */
138	        private static String primaryIdentifier(Owner owner) {
139	            return owner.getMemberId();
140	        }
141	
142	        private static Integer membershipLevel(Owner owner) {
143	            return owner.getMembershipLevel();
144	        }
145	
146	        /**
147	         * The owner's {@link Owner#getOwnerSegment() segment}, recomputed from the owner's version-2
148	         * identity at emit time.
149	         */
150	        private static String ownerSegment(Owner owner) {
151	            return owner.getOwnerSegment();
152	        }
153	    }
154	
155	    /**
156	     * The HTTP request header a client may send to make a create idempotent. When a create repeats
157	     * with a key already seen, the originally created owner is returned instead of a duplicate.
158	     */
159	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
160	
161	    /**
162	     * Remembers, per {@link #IDEMPOTENCY_KEY_HEADER Idempotency-Key}, the id of the owner that key's
163	     * first successful create produced, so a repeat of that create can return the same owner rather
164	     * than creating a duplicate.
165	     */
166	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
167	
168	    /**
169	     * Fixed public-holiday calendar. A registration date that lands on one of these dates is rolled
170	     * forward to the next non-holiday business day, in the same way weekends are.
171	     */
172	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
173	        LocalDate.of(2026, 1, 1),
174	        LocalDate.of(2026, 1, 26),
175	        LocalDate.of(2026, 4, 25),
176	        LocalDate.of(2026, 12, 25),
177	        LocalDate.of(2026, 12, 28));
178	
179	    private final ClinicService clinicService;
180	
181	    private final OwnerMapper ownerMapper;
182	
183	    private final PetMapper petMapper;
184	
185	    private final VisitMapper visitMapper;
186	
187	    private final AddressNormalizer addressNormalizer;
188	
189	    public OwnerRestControllerV1(ClinicService clinicService,
190	                                 OwnerMapper ownerMapper,
191	                                 PetMapper petMapper,
192	                                 VisitMapper visitMapper,
193	                                 AddressNormalizer addressNormalizer) {
194	        this.clinicService = clinicService;
195	        this.ownerMapper = ownerMapper;
196	        this.petMapper = petMapper;
197	        this.visitMapper = visitMapper;
198	        this.addressNormalizer = addressNormalizer;
199	    }
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
204	        Collection<Owner> owners;
205	        if (lastName != null) {
206	            owners = this.clinicService.findOwnerByLastName(lastName);
207	        } else {
208	            owners = this.clinicService.findAllOwners();
209	        }
210	        if (owners.isEmpty()) {
211	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
212	        }
213	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
214	    }
215	
216	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
217	    @Override
218	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
219	        Owner owner = this.clinicService.findOwnerById(ownerId);
220	        if (owner == null) {
221	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	        }
223	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
224	    }
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
229	        String idempotencyKey = currentIdempotencyKey();
230	        if (idempotencyKey != null) {
231	            Integer existingId = idempotentCreates.get(idempotencyKey);
232	            if (existingId != null) {
233	                Owner existing = this.clinicService.findOwnerById(existingId);
234	                if (existing != null) {
235	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
236	                }
237	            }
238	        }
239	
240	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
241	
242	        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
243	            && response.getBody() != null && response.getBody().getId() != null) {
244	            idempotentCreates.put(idempotencyKey, response.getBody().getId());
245	        }
246	        return response;
247	    }
248	
249	    /**
250	     * The non-blank {@link #IDEMPOTENCY_KEY_HEADER Idempotency-Key} header of the request currently
251	     * being handled, or {@code null} when the request carries no such header (or no request is bound
252	     * to the current thread). Used to make a repeated create return the originally created owner.
253	     */
254	    private String currentIdempotencyKey() {
255	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
256	            return null;
257	        }
258	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
259	        return (key == null || key.isBlank()) ? null : key;
260	    }
261	
262	    /**
263	     * Run the full owner-creation pipeline for a submitted {@link OwnerFieldsDto} and build its
264	     * response. The submitted fields are mapped to an {@link Owner}, which is
265	     * {@link #normalizeAndValidate(Owner) normalized and validated}, checked against the
266	     * {@link #isDailyLimitReached(LocalDate) daily creation limit}, {@link #assignHousehold(Owner)
267	     * assigned its household} and screened for {@link #checkForConflicts(Owner) conflicts};
268	     * a surviving owner then has its {@link #assignDerivedAttributes(Owner, boolean) derived
269	     * attributes} assigned, is persisted and audited. Returns the {@link #created(Owner) 201 Created}
270	     * response for the persisted owner, or throws {@link RejectedRequestException} with the status
271	     * the create must fail with ({@code 400 Bad Request}, {@code 429 Too Many Requests} or
272	     * {@code 409 Conflict}) when the owner cannot be created.
273	     */
274	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
275	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
276	
277	        normalizeAndValidate(owner);
278	        if (isDailyLimitReached(owner.getRegistrationDate())) {
279	            throw new RejectedRequestException(HttpStatus.TOO_MANY_REQUESTS);
280	        }
281	
282	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
283	        assignHousehold(owner);
284	
285	        checkForConflicts(owner);
286	
287	        assignDerivedAttributes(owner, sharesHousehold);
288	        this.clinicService.saveOwner(owner);
289	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
290	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
291	            owner.getMembershipLevel());
292	        emitOwnerCreatedEvent(owner);
293	        enqueueWelcomeNotification(owner);
294	        return created(owner);
295	    }
296	
297	    /**
298	     * Enqueue a welcome notification for a just-created owner by emitting a line on the {@code NOTIFY}
299	     * logger that carries the owner's id and its unified {@link Owner#getMemberId() memberId}, so a
300	     * downstream consumer can address the welcome to the newly registered owner.
301	     */
302	    private void enqueueWelcomeNotification(Owner owner) {
303	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
304	    }
305	
306	    /**
307	     * Emit the immutable {@link OwnerCreatedEvent} for a just-persisted owner as a JSON object on the
308	     * {@code AUDIT} logger. A fresh {@link #AUDIT_SEQ monotonic sequence} is stamped onto the event so
309	     * the order of creates is recoverable from the audit stream. The event carries the owner's primary
310	     * identifier, its unified memberId.
311	     */
312	    private void emitOwnerCreatedEvent(Owner owner) {
313	        OwnerCreatedEvent event = OwnerCreatedEvent.of(AUDIT_SEQ.incrementAndGet(), owner);
314	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
315	    }
316	
317	    /**
318	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
319	     * rejected. The owner's {@link #normalizeAddress(Owner) address is normalized} (a missing address
320	     * is rejected), its telephone is converted to E.164 (an unconvertible number is rejected), its
321	     * postcode is checked against its city's region, a registration date in the future is rejected,
322	     * and the effective registration date (the supplied one, or today when none was given) is rolled
323	     * onto a business day and stored back on the owner. Returns once the owner is valid and
324	     * normalized, or throws {@link RejectedRequestException} with the status the create must fail
325	     * with ({@code 400 Bad Request}) otherwise.
326	     */
327	    private void normalizeAndValidate(Owner owner) {
328	        if (!normalizeAddress(owner)) {
329	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST);
330	        }
331	        String telephone = toE164(owner.getTelephone());
332	        if (telephone == null) {
333	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST);
334	        }
335	        owner.setTelephone(telephone);
336	        if (isDisposableEmail(owner.getEmail())) {
337	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST);
338	        }
339	        if (!owner.isPostcodeValid()) {
340	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST);
341	        }
342	        if (owner.getRegistrationDate() != null
343	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
344	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST);
345	        }
346	        LocalDate effectiveDate = owner.getRegistrationDate() != null
347	            ? owner.getRegistrationDate() : LocalDate.now();
348	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
349	    }
350	
351	    /**
352	     * Normalize the owner's supplied address into its canonical stored form and report whether an
353	     * address was supplied at all. The owner may supply its address either as the structured
354	     * {@code addressLine1}/{@code addressLine2} fields or as the flat {@code address} field, which is
355	     * kept for backward compatibility; the structured form is preferred whenever a non-blank
356	     * {@code addressLine1} is present. Each supplied field is run through the {@link AddressNormalizer}
357	     * (trimmed, whitespace-collapsed, upper-cased, common street-type abbreviations expanded). When the
358	     * structured form is used, the normalized {@code addressLine1} and {@code addressLine2} are stored
359	     * back and the composed {@link Owner#getAddress() address} becomes the normalized
360	     * {@code addressLine1} with a single space and the normalized {@code addressLine2} appended when an
361	     * {@code addressLine2} is present; when the flat form is used, the normalized flat address is
362	     * stored and no structured lines are kept. Returns {@code true} once a non-blank address has been
363	     * normalized and stored, or {@code false} when neither form supplied an address, in which case the
364	     * create must be rejected with {@code 400 Bad Request}.
365	     */
366	    private boolean normalizeAddress(Owner owner) {
367	        String line1 = addressNormalizer.normalize(owner.getAddressLine1());
368	        if (!line1.isEmpty()) {
369	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
370	            owner.setAddressLine1(line1);
371	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
372	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
373	            return true;
374	        }
375	        String address = addressNormalizer.normalize(owner.getAddress());
376	        if (address.isEmpty()) {
377	            return false;
378	        }
379	        owner.setAddressLine1(null);
380	        owner.setAddressLine2(null);
381	        owner.setAddress(address);
382	        return true;
383	    }
384	
385	    /**
386	     * The set of disposable (throwaway) email domains that an owner's email may not use. An owner
387	     * whose email is hosted on one of these domains is rejected with {@code 400 Bad Request}.
388	     */
389	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
390	        "mailinator.com", "tempmail.com", "guerrillamail.com");
391	
392	    /**
393	     * Whether the given email is hosted on a {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable}
394	     * domain. The email is optional, so a {@code null} or empty email is not disposable; otherwise
395	     * its {@linkplain Owner#emailDomainOf(String) domain} (compared case-insensitively) is matched
396	     * against the blocklist.
397	     */
398	    private boolean isDisposableEmail(String email) {
399	        String domain = Owner.emailDomainOf(email);
400	        return domain != null && DISPOSABLE_EMAIL_DOMAINS.contains(domain);
401	    }
402	
403	    /**
404	     * Assign the owner its household link. The {@link #householdId(Owner) householdId} is computed
405	     * deterministically from the owner's lastName and postcode, so every owner sharing that
406	     * lastName and postcode is assigned the same value automatically, independent of whether the
407	     * owner declares it shares a household. The link is assigned before the
408	     * {@link #checkForConflicts(Owner) conflict checks} because it feeds the owner's
409	     * {@link #householdSize(String) household size} and {@link #membershipLevel(Owner) membership
410	     * level}.
411	     */
412	    private void assignHousehold(Owner owner) {
413	        owner.setHouseholdId(householdId(owner));
414	    }
415	
416	    /**
417	     * Screen the owner for a clash with an owner that already exists. An owner is rejected with
418	     * {@code 409 Conflict} when it {@linkplain #isDuplicateIdentity(Owner) duplicates an existing
419	     * owner's identity key} or when its {@link #isCityAtCapacity(String) city is already at
420	     * capacity}. Sharing a household (the same surname sound and postcode) but with a different
421	     * identity key is not a conflict: such an owner is admitted and later
422	     * {@linkplain #findSoftDuplicate(Owner) flagged as a possible duplicate}. Returns when the owner
423	     * clashes with nothing and may be created, or throws {@link RejectedRequestException} with
424	     * {@code 409 Conflict} when it clashes.
425	     */
426	    private void checkForConflicts(Owner owner) {
427	        if (isDuplicateIdentity(owner)) {
428	            throw new RejectedRequestException(HttpStatus.CONFLICT);
429	        }
430	        if (isCityAtCapacity(owner.getCity())) {
431	            throw new RejectedRequestException(HttpStatus.CONFLICT);
432	        }
433	    }
434	
435	    /**
436	     * Whether an existing owner already carries this owner's {@link Owner#getIdentityKey() identity
437	     * key}. This is the single hard-duplicate rule: two owners are duplicates exactly when their
438	     * identity keys are equal, and the second is rejected with {@code 409 Conflict}. Like the other
439	     * identity rules it considers only the {@linkplain #activeOwners() active owners}, so an owner
440	     * flagged {@linkplain Owner#isDeleted() deleted} never triggers a duplicate. The email-domain
441	     * blocklist is applied earlier, during {@link #normalizeAndValidate(Owner) validation}, so a
442	     * disposable-email owner is rejected before it reaches this check.
443	     */
444	    private boolean isDuplicateIdentity(Owner owner) {
445	        String identityKey = owner.getIdentityKey();
446	        return activeOwners().stream()
447	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
448	    }
449	
450	    /**
451	     * Build the {@code 201 Created} response for a persisted owner: its {@link OwnerDto} body and a
452	     * {@code Location} header pointing at {@code /api/owners/{id}}.
453	     */
454	    private ResponseEntity<OwnerDto> created(Owner owner) {
455	        HttpHeaders headers = new HttpHeaders();
456	        headers.setLocation(UriComponentsBuilder.newInstance()
457	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
458	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), headers, HttpStatus.CREATED);
459	    }
460	
461	    /**
462	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
463	     * {@link #memberId(Owner) memberId}, {@link #namesakeCount(String, String) namesakeCount},
464	     * {@link #isBulkSignup(LocalDate) bulk-signup warning}, {@link #isCityApproachingCapacity(String)
465	     * capacity warning}, {@link #householdSize(String)
466	     * householdSize} and {@link #membershipLevel(Owner) membershipLevel}. Each is computed from the
467	     * owner's own fields together with the owners already present, so this runs after the owner has
468	     * been validated and has passed the duplicate and capacity checks, and immediately before it is
469	     * persisted.
470	     */
471	    private void assignDerivedAttributes(Owner owner, boolean sharesHousehold) {
472	        owner.setMemberId(memberId(owner));
473	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
474	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
475	        owner.setCapacityWarning(isCityApproachingCapacity(owner.getCity()));
476	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
477	        owner.setMembershipLevel(membershipLevel(owner));
478	        assignPossibleDuplicate(owner, sharesHousehold);
479	        owner.setRiskFlag(isRiskFlagged(owner));
480	    }
481	
482	    /**
483	     * Whether a newly created owner should be flagged for review. True when any of these hold: the
484	     * owner is a {@linkplain Owner#getPossibleDuplicate() possible duplicate}, its email domain is
485	     * {@linkplain #isDisposableAdjacentEmail(String) disposable-adjacent}, or its city is over its
486	     * soft capacity (the city is {@linkplain #isCityApproachingCapacity(String) approaching capacity},
487	     * so its {@link Owner#getCapacityWarning() capacityWarning} is set); otherwise false. Computed
488	     * during {@link #assignDerivedAttributes(Owner, boolean)}, after the possible-duplicate and
489	     * capacity-warning attributes it reads have already been assigned.
490	     */
491	    private boolean isRiskFlagged(Owner owner) {
492	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
493	            || isDisposableAdjacentEmail(owner.getEmail())
494	            || Boolean.TRUE.equals(owner.getCapacityWarning());
495	    }
496	
497	    /**
498	     * Whether the given email's domain is disposable-adjacent: a subdomain of a known
499	     * {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable} domain (e.g. {@code x.mailinator.com}). An
500	     * exactly-disposable domain is rejected earlier during {@link #normalizeAndValidate(Owner)
501	     * validation}, so it never reaches here; a subdomain is admitted but still flagged as adjacent.
502	     * The email is optional, so a {@code null} or empty email is not disposable-adjacent; otherwise
503	     * its {@linkplain Owner#emailDomainOf(String) domain} (compared case-insensitively) is tested.
504	     */
505	    private boolean isDisposableAdjacentEmail(String email) {
506	        String domain = Owner.emailDomainOf(email);
507	        if (domain == null) {
508	            return false;
509	        }
510	        return DISPOSABLE_EMAIL_DOMAINS.stream()
511	            .anyMatch(disposable -> domain.endsWith("." + disposable));
512	    }
513	
514	    /**
515	     * The membership level to assign a newly created owner and store on it as its
516	     * {@link Owner#getMembershipLevel() membershipLevel}: the owner's own
517	     * {@linkplain Owner#getBaseMembershipLevel() base level} derived from its membershipPoints,
518	     * capped so it cannot exceed one above the current maximum membershipLevel among the owner's
519	     * existing {@linkplain #householdMembers(String) household members}. With no existing household
520	     * member no cap applies and the base level is used as-is. This is the single place the stored
521	     * membership level is derived; it runs during {@link #assignDerivedAttributes(Owner, boolean)},
