23	/**
24	 * Canonicalises a postal address into the single form used to store, compare and
25	 * identify owners' addresses, so that matching does not depend on incidental
26	 * differences in spacing, casing or the use of common abbreviations.
27	 *
28	 * <p>The canonical form trims surrounding whitespace, collapses internal runs of
29	 * whitespace to a single space, upper-cases the result and expands common street-type
30	 * abbreviations token-by-token ({@code ST -> STREET}, {@code RD -> ROAD},
31	 * {@code AVE -> AVENUE}). A {@code null} or blank address canonicalises to the empty
32	 * string.
33	 */
34	@Component
35	public class AddressNormalizer {
36	
37	    private static final Map<String, String> ABBREVIATIONS = Map.of(
38	        "ST", "STREET",
39	        "RD", "ROAD",
40	        "AVE", "AVENUE");
41	
42	    /**
43	     * Return the canonical form of {@code address} (see class documentation), or the
44	     * empty string when {@code address} is {@code null} or blank.
45	     */
46	    public String normalize(String address) {
47	        if (address == null) {
48	            return "";
49	        }
50	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
51	        if (collapsed.isEmpty()) {
52	            return "";
53	        }
54	        String[] tokens = collapsed.split(" ");
55	        StringBuilder sb = new StringBuilder(collapsed.length());
56	        for (int i = 0; i < tokens.length; i++) {
57	            if (i > 0) {
58	                sb.append(' ');
59	            }
60	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
61	        }
62	        return sb.toString();
63	    }
64	}
