334	    /**
335	     * The fixed length of the tail that every {@linkplain #getMemberId() memberId} carries after its
336	     * {@code <REGION>} prefix: the 2-digit fiscal-year code, the 8-character HASH8 and the single Luhn
337	     * check digit ({@code 2 + 8 + 1 = 11}). The region prefix is therefore everything in the memberId
338	     * (before any collision suffix) up to this trailing block, so the region and fiscal-year segments
339	     * are read back from the memberId rather than re-derived.
340	     */
341	    private static final int MEMBER_ID_TAIL = 11;
342	
343	    /**
344	     * The owner's base memberId, formatted {@code '<REGION><FY><HASH8><CHK>'}: the
345	     * {@linkplain #getRegion() region} derived from the owner's postcode (or {@link #UNKNOWN_REGION}
346	     * when the postcode maps to no known region), the 2-digit {@linkplain #fiscalYearCode() fiscal-year
347	     * code} FY, the 8 upper-case hex HASH8 (the first 8 hex characters of the SHA-256 of the normalized
348	     * (E.164) telephone concatenated with the lastName, the same HASH8 the region-and-hash identity
349	     * uses), and a single Luhn {@linkplain #luhnCheckDigit(String) check digit} CHK computed over the
350	     * decimal digits of {@code <REGION><FY><HASH8>}, e.g. {@code 'NSW273C1A9F2B4'}. This is the single
351	     * source of the owner's identity; the stored {@linkplain #getMemberId() memberId} is this value
352	     * (with a collision suffix appended only when it clashes with an existing owner's), and the owner's
353	     * {@linkplain #getFiscalYear() fiscal year} is read back from it. Its {@code <REGION>} component is
354	     * the {@linkplain #regionCode() region code} the identifiers are built from.
355	     */
356	    public String computeMemberId() {
357	        String hash8 = HashUtils.sha256Hex(this.telephone + this.getLastName()).toUpperCase().substring(0, 8);
358	        String prefix = regionCode() + fiscalYearCode() + hash8;
359	        return prefix + luhnCheckDigit(prefix);
360	    }
361	
362	    /**
363	     * The {@linkplain #getMemberId() memberId} without its collision suffix: the memberId up to the
364	     * first {@code '-'} (the {@code '-<n>'} suffix appended only to de-duplicate a clashing id), or
365	     * {@code null} when the owner has no memberId. This is the {@code '<REGION><FY><HASH8><CHK>'} base
366	     * from which the {@linkplain #getFiscalYear() fiscal year} is read.
367	     */
368	    private String memberIdBase() {
369	        if (this.memberId == null) {
370	            return null;
371	        }
372	        int dash = this.memberId.indexOf('-');
373	        return dash < 0 ? this.memberId : this.memberId.substring(0, dash);
374	    }
375	
376	    /**
377	     * The owner's fiscal year, formatted {@code 'FY<YY>'}, e.g. {@code 'FY27'}. The two YY digits are
378	     * read from the {@linkplain #getMemberId() memberId} (the {@code <FY>} segment embedded in it), so
379	     * the fiscal-year value shares the owner's single memberId identity; for an owner that has no
380	     * memberId the digits fall back to the {@linkplain #fiscalYearCode() fiscal-year code} of the
381	     * (business-day-adjusted) {@link #registrationDate}. The fiscal year starts on 1 July and is
382	     * labelled by the calendar year in which it ends.
383	     */
384	    public String getFiscalYear() {
385	        String base = memberIdBase();
386	        if (base != null && base.length() >= MEMBER_ID_TAIL) {
387	            return "FY" + base.substring(base.length() - MEMBER_ID_TAIL, base.length() - MEMBER_ID_TAIL + 2);
388	        }
389	        return "FY" + fiscalYearCode();
390	    }
391	
392	    /**
393	     * The two-digit fiscal-year code {@code '<YY>'}: the last two digits of the
394	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the (business-day-adjusted)
395	     * {@link #registrationDate}, zero-padded, e.g. {@code '27'}. This is the FY segment embedded in the
396	     * owner's {@linkplain #computeMemberId() memberId} at creation, and the fallback the
397	     * {@linkplain #getFiscalYear() fiscal year} reads when no memberId is present.
398	     */
399	    private String fiscalYearCode() {
400	        return String.format("%02d", fiscalYearOf(this.registrationDate) % 100);
401	    }
402	
403	    /**
404	     * The fiscal year that contains the given date, identified by the calendar year in which it
405	     * ends. The fiscal year starts on 1 July, so a date in July through December belongs to the
406	     * fiscal year ending in the following calendar year, while a date in January through June
407	     * belongs to the fiscal year ending in the same calendar year.
408	     */
409	    private static int fiscalYearOf(LocalDate date) {
410	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
411	    }
412	
413	    /**
414	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
415	     * contained in {@code value}. Reading the digits right to left, every second one is
416	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
417	     * digits are summed, and the check digit is the amount that must be added to that sum to
418	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
419	     * the digit is taken over exactly the digits the string carries.
420	     */
421	    private static int luhnCheckDigit(String value) {
422	        int sum = 0;
423	        boolean doubling = true;
424	        for (int i = value.length() - 1; i >= 0; i--) {
425	            char c = value.charAt(i);
426	            if (c < '0' || c > '9') {
427	                continue;
428	            }
429	            int digit = c - '0';
430	            if (doubling) {
431	                digit *= 2;
432	                if (digit > 9) {
433	                    digit -= 9;
434	                }
435	            }
436	            sum += digit;
437	            doubling = !doubling;
438	        }
439	        return (10 - (sum % 10)) % 10;
440	    }
