546	    /**
547	     * The region derived from this owner's postcode alone: the region whose fixed
548	     * {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the postcode, or {@code null}
549	     * when the postcode is absent, not four digits, or in no known range. Defaulted to
550	     * {@link #UNKNOWN_REGION} by {@link #regionOrUnknown()}, it is the source of both the owner's
551	     * user-facing {@linkplain #getLocality() locality} and the {@linkplain #regionCode() region code}
552	     * built into the owner's {@linkplain #computeMemberId() memberId}. It is the single place a region
553	     * is read from an owner's postcode, so every rule keyed by the postcode-derived region shares one
554	     * derivation.
555	     */
556	    public String getRegion() {
557	        return regionOfPostcode(this.postcode);
558	    }
