560	    /**
561	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
562	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
563	     * no known range.
564	     */
565	    private static String regionOfPostcode(String postcode) {
566	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
567	            return null;
568	        }
569	        int value = Integer.parseInt(postcode);
570	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
571	            int[] range = entry.getValue();
572	            if (value >= range[0] && value <= range[1]) {
573	                return entry.getKey();
574	            }
575	        }
576	        return null;
577	    }
578	
579	    /**
580	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
581	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
582	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
583	     */
584	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
585	        "NSW", new int[] {2000, 2099},
586	        "VIC", new int[] {3000, 3099},
587	        "QLD", new int[] {4000, 4099});
588	
589	    /**
590	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
591	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
592	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
593	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
594	     * city with no known region accepts any 4-digit postcode.
595	     */
596	    public boolean isPostcodeValid() {
597	        if (this.postcode == null) {
598	            return true;
599	        }
600	        if (!this.postcode.matches("[0-9]{4}")) {
601	            return false;
602	        }
603	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
604	        if (range == null) {
605	            return true;
606	        }
607	        int value = Integer.parseInt(this.postcode);
608	        return value >= range[0] && value <= range[1];
609	    }
