611	    /**
612	     * The national (subscriber) digit count required by each known country calling code, keyed by
613	     * the code's digits (without the leading {@code '+'}): {@code '+1'} carries 10 national digits
614	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
615	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
616	     * re-derived elsewhere.
617	     */
618	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
619	        "1", 10,
620	        "61", 9);
621	
622	    /**
623	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
624	     * E.164 digit string, choosing the longest matching code known to
625	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
626	     * country code. This is the single place a country code is read from an E.164 number, so every
627	     * rule keyed by that code shares one derivation.
628	     */
629	    private static String countryCodeOf(String e164Digits) {
630	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
631	            .filter(e164Digits::startsWith)
632	            .max(Comparator.comparingInt(String::length))
633	            .orElse(null);
634	    }
635	
636	    /**
637	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
638	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
639	     * known code wins; a number whose country code is not recognised passes this check (its length is
640	     * then governed only by the general E.164 bound), while a recognised code must be followed by
641	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
642	     */
643	    public static boolean hasValidNationalLength(String e164Digits) {
644	        String countryCode = countryCodeOf(e164Digits);
645	        if (countryCode == null) {
646	            return true;
647	        }
648	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
649	    }
