651	    /**
652	     * The owner's membership points: they start at 0, gain 2 when an email is present, gain 1 when
653	     * namesakeCount is 0, gain 2 for a {@linkplain #hasLargeHousehold() household of 3 or more}, and
654	     * gain 3 when the owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one
655	     * elapsed fiscal year. The email, namesake and household factors are available on creation; the
656	     * tenure factor is reached only once at least one fiscal-year boundary has passed.
657	     */
658	    public Integer getMembershipPoints() {
659	        int points = 0;
660	        if (hasEmail()) {
661	            points += 2;
662	        }
663	        if (hasNoNamesakes()) {
664	            points += 1;
665	        }
666	        if (hasLargeHousehold()) {
667	            points += 2;
668	        }
669	        if (hasQualifyingTenure()) {
670	            points += 3;
671	        }
672	        return points;
673	    }
